type TtsRequestVoiceTransformEffect = Union[TtsRequestVoiceTransformEffectAuditoriumEcho, TtsRequestVoiceTransformEffectRobotic, TtsRequestVoiceTransformEffectSpaciousEcho, TtsRequestVoiceTransformEffectTelephone]

class TtsRequestVoiceTransform(TypedDict):
    # TypeScript field: brightness.
    brightness: ReadOnly[NotRequired[float]]
    # TypeScript field: crispness.
    crispness: ReadOnly[NotRequired[float]]
    # TypeScript field: effect.
    effect: ReadOnly[NotRequired[TtsRequestVoiceTransformEffect]]
    # TypeScript field: softness.
    softness: ReadOnly[NotRequired[float]]

class TtsRequest(TypedDict):
    # TypeScript field: accent.
    # Accent to use independently of the synthesis language.
    accent: ReadOnly[NotRequired[str]]
    # TypeScript field: accentBlend.
    # Blend a base accent with a target accent; the ratio is 0 for the base and 1 for the target.
    accent_blend: ReadOnly[NotRequired[TtsRequestAccentBlend]]
    # TypeScript field: accentPreservation.
    # Preserve the source voice's accent in generated speech.
    accent_preservation: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: apiVersion.
    # Provider API generation when it changes the available request capabilities.
    api_version: ReadOnly[NotRequired[str]]
    # TypeScript field: audioDelivery.
    # Deliver audio immediately as generated, or pace byte emission for playback.
    audio_delivery: ReadOnly[NotRequired[TtsRequestAudioDelivery]]
    # TypeScript field: audioEnhancement.
    # Apply provider audio cleanup and loudness enhancement to generated output.
    audio_enhancement: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: audioProcessingProfile.
    # Existing audio post-processing chain identifier.
    audio_processing_profile: ReadOnly[NotRequired[str]]
    # TypeScript field: audioRetention.
    # Allow the provider to retain a generated audio file; false requests inline audio without file retention.
    audio_retention: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: automaticGainControl.
    # Automatically adjust output gain levels.
    automatic_gain_control: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: automaticTextFlushing.
    # Let the provider adapt text flushing for low latency and speech quality.
    automatic_text_flushing: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: completionDelayMs.
    # Provider grace period after the last generated chunk before completion.
    completion_delay_ms: ReadOnly[NotRequired[float]]
    # TypeScript field: conditionOnPreviousChunks.
    # Use previous generated audio as conditioning for subsequent chunks.
    condition_on_previous_chunks: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: contentRetentionDays.
    # Opt into provider content deletion after this many days; not zero-retention.
    content_retention_days: ReadOnly[NotRequired[float]]
    # TypeScript field: contextAfter.
    # Text or generation identifiers providing following speech context.
    context_after: ReadOnly[NotRequired[TtsRequestContextAfter]]
    # TypeScript field: contextBefore.
    # Text or previous generation identifiers providing preceding speech context.
    context_before: ReadOnly[NotRequired[TtsRequestContextBefore]]
    # TypeScript field: continuation.
    # Carry synthesis state across incremental fragments in one named context. Completion semantics are provider-specific.
    continuation: ReadOnly[NotRequired[TtsRequestContinuation]]
    # TypeScript field: deliveryMode.
    # Discrete delivery policy balancing consistency and expressive variation.
    delivery_mode: ReadOnly[NotRequired[TtsRequestDeliveryMode]]
    # TypeScript field: deliveryReference.
    # Reference performance identifier used to guide delivery independently of voice identity.
    delivery_reference: ReadOnly[NotRequired[str]]
    # TypeScript field: deliveryVariance.
    # Variation within the generated delivery, from 0 to 1.
    delivery_variance: ReadOnly[NotRequired[float]]
    # TypeScript field: durationStretching.
    # Enable extended duration stretching of generated speech.
    duration_stretching: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: earlyStopThreshold.
    # Generation early-stopping threshold, from 0 to 1.
    early_stop_threshold: ReadOnly[NotRequired[float]]
    # TypeScript field: effectsProfiles.
    # Ordered audio processing profiles for the target playback device.
    effects_profiles: ReadOnly[NotRequired[Sequence[str]]]
    # TypeScript field: emotion.
    # Requested emotional delivery.
    emotion: ReadOnly[NotRequired[str]]
    # TypeScript field: emotionBlend.
    # Relative emotional tendencies on the provider's scale, not normalized probabilities.
    emotion_blend: ReadOnly[NotRequired[TtsRequestEmotionBlend]]
    # TypeScript field: emotionIntensity.
    # Strength of emotional expression on the provider's scale.
    emotion_intensity: ReadOnly[NotRequired[float]]
    # TypeScript field: emotionSource.
    # Prefer contextual text emotion or the selected voice sample's emotion.
    emotion_source: ReadOnly[NotRequired[TtsRequestEmotionSource]]
    # TypeScript field: features.
    # Provider feature flags enabled for this synthesis request.
    features: ReadOnly[NotRequired[Sequence[str]]]
    # TypeScript field: formulaReading.
    # Interpret mathematical expressions in the specified notation.
    formula_reading: ReadOnly[NotRequired[TtsRequestFormulaReading]]
    # TypeScript field: frequencyPenalty.
    # Penalize audio tokens according to how frequently they have occurred.
    frequency_penalty: ReadOnly[NotRequired[float]]
    # TypeScript field: includeUsage.
    # Request native usage accounting when it requires an alternate response mode.
    include_usage: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: inferenceSteps.
    # Number of inference steps used to generate speech.
    inference_steps: ReadOnly[NotRequired[float]]
    # TypeScript field: inputType.
    # Interpretation of the input text.
    input_type: ReadOnly[NotRequired[TtsRequestInputType]]
    # TypeScript field: instructions.
    # Natural-language guidance for the spoken delivery.
    instructions: ReadOnly[NotRequired[str]]
    # TypeScript field: language.
    # Language or locale used for synthesis.
    language: ReadOnly[NotRequired[str]]
    # TypeScript field: languageTextNormalization.
    # Apply a language-specific normalization pass independently of general normalization.
    language_text_normalization: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: latencyOptimization.
    # Degree to which synthesis quality may be traded for lower first-audio latency.
    latency_optimization: ReadOnly[NotRequired[TtsRequestLatencyOptimization]]
    # TypeScript field: lexicon.
    # Pronunciation lexicon name or names.
    lexicon: ReadOnly[NotRequired[TtsRequestLexicon]]
    # TypeScript field: lexiconUrl.
    # URL of an existing pronunciation lexicon.
    lexicon_url: ReadOnly[NotRequired[str]]
    # TypeScript field: longTextMode.
    # Enable a provider's extended long-text generation mode.
    long_text_mode: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: loudnessNormalization.
    # Normalize output loudness independently of the requested gain.
    loudness_normalization: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: maxAudioTokens.
    # Maximum audio tokens generated per text chunk.
    max_audio_tokens: ReadOnly[NotRequired[float]]
    # TypeScript field: maxBufferDelayMs.
    # Maximum provider text-buffering delay before generation begins.
    max_buffer_delay_ms: ReadOnly[NotRequired[float]]
    # TypeScript field: metadata.
    # Provider-side metadata attached to the synthesis request.
    metadata: ReadOnly[NotRequired[Mapping[str, JsonValue]]]
    # TypeScript field: minP.
    # Minimum token probability relative to the most likely token, from 0 to 1.
    min_p: ReadOnly[NotRequired[float]]
    # TypeScript field: minTextChunkLength.
    # Minimum characters before splitting a new synthesis chunk.
    min_text_chunk_length: ReadOnly[NotRequired[float]]
    # TypeScript field: model.
    # Provider synthesis model or engine.
    model: ReadOnly[NotRequired[str]]
    # TypeScript field: modelImprovementOptOut.
    # Opt this request out of the provider's model-improvement program. May affect pricing.
    model_improvement_opt_out: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: namedEntityPronunciationEnhancement.
    # Improve pronunciation of names, brands, and other named entities.
    named_entity_pronunciation_enhancement: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: numberPronunciationLanguage.
    # Language for reading numbers independently of the synthesis language.
    number_pronunciation_language: ReadOnly[NotRequired[str]]
    # TypeScript field: output.
    # Requested audio representation.
    output: ReadOnly[NotRequired[TtsRequestOutput]]
    # TypeScript field: pacingBias.
    # Delivery pacing bias: zero is neutral, negative is faster, positive is slower. Not a speed multiplier.
    pacing_bias: ReadOnly[NotRequired[float]]
    # TypeScript field: pitchBias.
    # Pitch adjustment on the provider's scale, when not specified in semitones.
    pitch_bias: ReadOnly[NotRequired[float]]
    # TypeScript field: pitchSemitones.
    # Pitch adjustment in semitones.
    pitch_semitones: ReadOnly[NotRequired[float]]
    # TypeScript field: preferredLanguages.
    # Ordered language or locale preferences for a multilingual voice.
    preferred_languages: ReadOnly[NotRequired[Sequence[str]]]
    # TypeScript field: presencePenalty.
    # Penalize audio tokens that have already occurred, independently of frequency.
    presence_penalty: ReadOnly[NotRequired[float]]
    # TypeScript field: processingPriority.
    # Scheduling priority, independent of synthesis quality/latency tradeoffs.
    processing_priority: ReadOnly[NotRequired[TtsRequestProcessingPriority]]
    # TypeScript field: promptCacheKey.
    # Cache affinity hint for repeated synthesis prompts.
    prompt_cache_key: ReadOnly[NotRequired[str]]
    # TypeScript field: pronunciationDictionaries.
    # Ordered pronunciation dictionary references, with optional pinned versions.
    pronunciation_dictionaries: ReadOnly[NotRequired[Sequence[TtsRequestPronunciationDictionariesItem]]]
    # TypeScript field: pronunciationDictionarySelection.
    # Select dictionaries within a scope; omitted IDs use its active defaults, while an empty list disables them.
    pronunciation_dictionary_selection: ReadOnly[NotRequired[TtsRequestPronunciationDictionarySelection]]
    # TypeScript field: randomSeed.
    # Seed used by providers that support deterministic sampling.
    random_seed: ReadOnly[NotRequired[float]]
    # TypeScript field: referenceAudio.
    # Reference audio used for voice conditioning, independent of an existing voice identifier.
    reference_audio: ReadOnly[NotRequired[bytes]]
    # TypeScript field: referenceAudioEnhancement.
    # Clean up the source recording behind the selected voice.
    reference_audio_enhancement: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: referenceAudioTrimming.
    # Trim non-speech portions from reference audio before voice conditioning.
    reference_audio_trimming: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: referenceEmphasis.
    # Balance reference similarity against expressive variation in controllable synthesis.
    reference_emphasis: ReadOnly[NotRequired[TtsRequestReferenceEmphasis]]
    # TypeScript field: referenceSamples.
    # Voice-conditioning recordings paired with their exact transcripts.
    reference_samples: ReadOnly[NotRequired[Sequence[TtsRequestReferenceSamplesItem]]]
    # TypeScript field: repetitionPenalty.
    # Penalty for repeating audio patterns.
    repetition_penalty: ReadOnly[NotRequired[float]]
    # TypeScript field: replacements.
    # Phrase-to-pronunciation substitutions.
    replacements: ReadOnly[NotRequired[Sequence[TtsRequestReplacementsItem]]]
    # TypeScript field: requestId.
    # Caller-supplied request correlation label, not a provider-generated identifier.
    request_id: ReadOnly[NotRequired[str]]
    # TypeScript field: safetySettings.
    # Category-specific content filtering.
    safety_settings: ReadOnly[NotRequired[Sequence[TtsRequestSafetySettingsItem]]]
    # TypeScript field: segmentation.
    # Whether incremental text waits for sentence boundaries or is synthesized immediately.
    segmentation: ReadOnly[NotRequired[TtsRequestSegmentation]]
    # TypeScript field: segments.
    # Ordered speech and silence in one composed output; provider types enforce valid segment shapes.
    segments: ReadOnly[NotRequired[Sequence[TtsRequestSegmentsItem]]]
    # TypeScript field: sessionId.
    # Caller-supplied session correlation label, not a provider-generated identifier.
    session_id: ReadOnly[NotRequired[str]]
    # TypeScript field: speakerGender.
    # Speaker gender used for language-specific synthesis decisions.
    speaker_gender: ReadOnly[NotRequired[TtsRequestSpeakerGender]]
    # TypeScript field: speakers.
    # Indexed speakers for dialogue, each with an existing voice and/or reference recordings.
    speakers: ReadOnly[NotRequired[Sequence[TtsRequestSpeakersItem]]]
    # TypeScript field: speed.
    # Speech speed multiplier.
    speed: ReadOnly[NotRequired[float]]
    # TypeScript field: speedBias.
    # Native speaking-rate bias: zero is neutral and positive is faster; not a multiplier.
    speed_bias: ReadOnly[NotRequired[float]]
    # TypeScript field: splitTurns.
    # Allow the provider to split input turns into smaller natural speech segments.
    split_turns: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: stability.
    # Voice consistency, from 0 (more expressive) to 1 (more stable).
    stability: ReadOnly[NotRequired[float]]
    # TypeScript field: styleExaggeration.
    # Exaggeration of the source voice's speaking style, on the provider's scale.
    style_exaggeration: ReadOnly[NotRequired[float]]
    # TypeScript field: subtitleFormat.
    # Request a native subtitle artifact, independently of normalized timestamp tracks.
    subtitle_format: ReadOnly[NotRequired[TtsRequestSubtitleFormat]]
    # TypeScript field: tags.
    # Usage-reporting labels attached to this request.
    tags: ReadOnly[NotRequired[Sequence[str]]]
    # TypeScript field: targetDurationMs.
    # Target synthesized duration in milliseconds; some providers exclude a simultaneous speed multiplier.
    target_duration_ms: ReadOnly[NotRequired[float]]
    # TypeScript field: targetLoudnessLufs.
    # Requested absolute loudness in LUFS, independent of relative volume scaling.
    target_loudness_lufs: ReadOnly[NotRequired[float]]
    # TypeScript field: temperature.
    # Sampling temperature; supported bounds depend on the provider.
    temperature: ReadOnly[NotRequired[float]]
    # TypeScript field: text.
    # Text to synthesize, supplied whole or incrementally when the provider supports streaming input.
    text: ReadOnly[NotRequired[TtsRequestText]]
    # TypeScript field: textBuffering.
    # Buffer incremental text before synthesis.
    text_buffering: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: textBufferThreshold.
    # Character-count threshold that triggers synthesis of buffered input.
    text_buffer_threshold: ReadOnly[NotRequired[float]]
    # TypeScript field: textBufferThresholds.
    # Successive character-count thresholds for incremental text buffering.
    text_buffer_thresholds: ReadOnly[NotRequired[Sequence[float]]]
    # TypeScript field: textChunkLength.
    # Target number of text characters per synthesis chunk.
    text_chunk_length: ReadOnly[NotRequired[float]]
    # TypeScript field: textFlushDelayMs.
    # Idle time before flushing buffered text; some providers may flush complete sentences sooner.
    text_flush_delay_ms: ReadOnly[NotRequired[float]]
    # TypeScript field: textMarkup.
    # Opt into native inline text syntax; these controls are independent of general text normalization.
    text_markup: ReadOnly[NotRequired[TtsRequestTextMarkup]]
    # TypeScript field: textNormalization.
    # Whether written text is normalized to spoken form before synthesis.
    text_normalization: ReadOnly[NotRequired[TtsRequestTextNormalization]]
    # TypeScript field: textSplitter.
    # Text splitting and voice binding, supplied inline or by saved identifier. Provider types enforce the valid configurations.
    text_splitter: ReadOnly[NotRequired[TtsRequestTextSplitter]]
    # TypeScript field: timestampDelivery.
    # Deliver alignment with its audio chunk, or later on an independent timeline.
    timestamp_delivery: ReadOnly[NotRequired[TtsRequestTimestampDelivery]]
    # TypeScript field: timestampGranularity.
    # Timing detail requested alongside audio; an array selects multiple supported kinds.
    timestamp_granularity: ReadOnly[NotRequired[TtsRequestTimestampGranularity]]
    # TypeScript field: timestampText.
    # Whether timestamps describe the original or normalized spoken text.
    timestamp_text: ReadOnly[NotRequired[TtsRequestTimestampText]]
    # TypeScript field: topK.
    # Maximum number of token candidates considered during sampling.
    top_k: ReadOnly[NotRequired[float]]
    # TypeScript field: topP.
    # Nucleus sampling probability mass, from 0 to 1.
    top_p: ReadOnly[NotRequired[float]]
    # TypeScript field: trailingSilenceMs.
    # Silence appended after an utterance, in milliseconds.
    trailing_silence_ms: ReadOnly[NotRequired[float]]
    # TypeScript field: turns.
    # Dialogue turns, supplied whole or incrementally when supported.
    turns: ReadOnly[NotRequired[TtsRequestTurns]]
    # TypeScript field: vividExpression.
    # Enable the provider's more expressive delivery mode.
    vivid_expression: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: voice.
    # Provider voice identifier.
    voice: ReadOnly[NotRequired[TtsRequestPronunciationDictionarySelectionIdsItem]]
    # TypeScript field: voiceBlend.
    # Blend existing voices using relative weights instead of selecting one voice.
    voice_blend: ReadOnly[NotRequired[Sequence[TtsRequestVoiceBlendItem]]]
    # TypeScript field: voiceBoost.
    # Strengthen the influence of the voice prompt on generated speech.
    voice_boost: ReadOnly[NotRequired[TtsRequestAccentPreservation]]
    # TypeScript field: voiceDescription.
    # Design a voice from a description, rather than directing an existing voice's delivery.
    voice_description: ReadOnly[NotRequired[str]]
    # TypeScript field: voiceGuidance.
    # Strength of voice-conditioning guidance, on the provider's scale.
    voice_guidance: ReadOnly[NotRequired[float]]
    # TypeScript field: voiceName.
    # Select a saved voice by name instead of identifier.
    voice_name: ReadOnly[NotRequired[str]]
    # TypeScript field: voiceSimilarity.
    # How closely generated speech should resemble the source voice, from 0 to 1.
    voice_similarity: ReadOnly[NotRequired[float]]
    # TypeScript field: voiceSource.
    # Namespace of an existing voice, independent of selecting it by ID or name.
    voice_source: ReadOnly[NotRequired[TtsRequestSpeakersItemVoiceSource]]
    # TypeScript field: voiceStyle.
    # Saved delivery style identifier belonging to the selected voice.
    voice_style: ReadOnly[NotRequired[str]]
    # TypeScript field: voiceTransform.
    # Post-synthesis voice coloration and acoustic effects, independent of speaking pitch.
    voice_transform: ReadOnly[NotRequired[TtsRequestVoiceTransform]]
    # TypeScript field: volumeDb.
    # Output gain adjustment in decibels, independent of linear volume scaling.
    volume_db: ReadOnly[NotRequired[float]]
    # TypeScript field: volumeScale.
    # Output volume multiplier.
    volume_scale: ReadOnly[NotRequired[float]]
